// Face-embedding model facts (API-CONTRACT §2.x `accepted_models`). Pure TS, so it
// can be loaded in Node tests. The native loader lives in ./loadModel.ts.
//
// The .tflite file is generated by scripts/face-model.sh from the official InsightFace buffalo_s
// release. Its weights are for NON-COMMERCIAL RESEARCH ONLY (assets/models/NOTICE-w600k_mbf.txt).

export const FACE_MODEL = {
  /** `model_name` / `accepted_models[].name` (API-CONTRACT, DATA-MODEL face_embeddings). */
  name: 'w600k_mbf',
  /** `model_version` / `accepted_models[].version`. */
  version: 'buffalo_s-fp32',
  dim: 512,
  /** NHWC, float32 (onnx2tf moved the ONNX NCHW input to NHWC). */
  inputShape: [1, 112, 112, 3] as const,
  outputShape: [1, 512] as const,
  fileName: 'w600k_mbf_float32.tflite',
  /** sha256 of the committed file, as printed by scripts/face-model.sh. */
  sha256: 'ca17b05ac6e92ff819d81191d865e3864f4e6779df60468f0db547c982091033',
  sizeBytes: 13_635_536,
} as const;

/** Number of float32 values in one input image (1 × 112 × 112 × 3 = 37,632). */
export const FACE_INPUT_FLOATS: number = FACE_MODEL.inputShape.reduce<number>((a, b) => a * b, 1);
/** Byte length of one input tensor. fast-tflite 3.0.1 does not check this, so callers must. */
export const FACE_INPUT_BYTES = FACE_INPUT_FLOATS * Float32Array.BYTES_PER_ELEMENT;

export interface TensorInfo {
  name: string;
  dataType: string;
  shape: number[];
}

/**
 * Checks the loaded model's tensors against FACE_MODEL. fast-tflite 3.0.1 silently runs a
 * wrong-size input on stale data, so the app checks shapes once at load time.
 * Returns a list of problems; an empty list means the model matches.
 */
export function checkModelTensors(inputs: TensorInfo[], outputs: TensorInfo[]): string[] {
  const problems: string[] = [];
  const same = (a: readonly number[], b: readonly number[]) =>
    a.length === b.length && a.every((v, i) => v === b[i]);
  if (inputs.length !== 1) problems.push(`expected 1 input tensor, got ${inputs.length}`);
  if (outputs.length !== 1) problems.push(`expected 1 output tensor, got ${outputs.length}`);
  const input = inputs[0];
  const output = outputs[0];
  if (input) {
    if (input.dataType !== 'float32')
      problems.push(`input dataType ${input.dataType}, not float32`);
    if (!same(input.shape, FACE_MODEL.inputShape))
      problems.push(
        `input shape [${input.shape.join(',')}], not [${FACE_MODEL.inputShape.join(',')}]`,
      );
  }
  if (output) {
    if (output.dataType !== 'float32')
      problems.push(`output dataType ${output.dataType}, not float32`);
    if (!same(output.shape, FACE_MODEL.outputShape))
      problems.push(
        `output shape [${output.shape.join(',')}], not [${FACE_MODEL.outputShape.join(',')}]`,
      );
  }
  return problems;
}

/**
 * Copies a raw output buffer into a fresh Float32Array right away (fast-tflite reuses output
 * buffers across calls) and checks that it is a finite 512-d vector.
 */
export function copyEmbeddingOutput(buffer: ArrayBuffer): Float32Array {
  const view = new Float32Array(buffer);
  if (view.length !== FACE_MODEL.dim) {
    throw new Error(`embedding has ${view.length} values, expected ${FACE_MODEL.dim}`);
  }
  const copy = Float32Array.from(view);
  for (let i = 0; i < copy.length; i++) {
    if (!Number.isFinite(copy[i])) throw new Error(`embedding value ${i} is not finite`);
  }
  return copy;
}

/** L2-normalises in place and returns the pre-normalisation norm. Throws on a zero vector. */
export function l2NormalizeInPlace(v: Float32Array): number {
  let sum = 0;
  for (let i = 0; i < v.length; i++) sum += (v[i] as number) * (v[i] as number);
  const norm = Math.sqrt(sum);
  if (!(norm > 0)) throw new Error('cannot normalise a zero vector');
  for (let i = 0; i < v.length; i++) v[i] = (v[i] as number) / norm;
  return norm;
}
